/* saleson.shop.slave.SlaveOrderMapper.getAllOrderCountByParamForManager */ SELECT COUNT(*)
FROM (
SELECT OI.*
, IFNULL(U.BIRTHDAY,'') AS BIRTHDAY
FROM ( SELECT * FROM ( SELECT O.LOGIN_ID, O.BUYER_NAME, OI.*, OSI.RECEIVE_NAME, (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV WHERE LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM, IFNULL(S.SELLER_NAME, '') AS SELLER_NAME, IFNULL(S.COMPANY_NAME, '') AS COMPANY_NAME, OI.USER_ID AS OI_USER_ID,
(SELECT USER_NAME FROM OP_USER WHERE USER_ID = OI.USER_ID) AS USER_NAME_ENC
, O.MOBILE , OSI.RECEIVE_MOBILE , OSI.RECEIVE_ZIPCODE , OSI.RECEIVE_NEW_ZIPCODE , OSI.RECEIVE_ADDRESS , OSI.RECEIVE_ADDRESS_DETAIL , OSI.MEMO , (SELECT OP.APPROVAL_TYPE FROM OP_ORDER_PAYMENT OP WHERE OI.ORDER_CODE = OP.ORDER_CODE AND OI.ORDER_SEQUENCE = OP.ORDER_SEQUENCE) AS APPROVAL_TYPE
, CASE WHEN OI.CAMPAIGN_CODE = 'MOBILE' THEN 'Y' ELSE 'N' END AS MOBILE_ITEM_YN FROM OP_ORDER_ITEM OI
INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE
INNER JOIN OP_ITEM OT ON OI.ITEM_CODE = OT.ITEM_CODE
JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND OI.SELLER_ID = #{sellerId} AND OI.DELIVERY_TYPE = '2'
AND OI.ORDER_STATUS IN
#{status}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID > #{sellerId}
AND OI.DELIVERY_TYPE = #{deliveryType}
AND OI.ORDER_STATUS IN
#{status}
AND OI.ORDER_CODE IN
#{orderCode}
AND OI.ORDER_CODE = #{orderCode}
AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.ORDER_STATUS IN
#{orderStatus}
AND OI.ORDER_STATUS = #{orderStatus}
AND OI.CANCEL_FLAG = #{cancelFlag}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y' AND O.BUYER_NAME = #{guestUserName} AND O.MOBILE = #{guestPhoneNumber}
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND OI.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime}, '9999')
AND O.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime} , '9999')
AND #{searchDateType} BETWEEN CONCAT(#{searchStartDate}, '000000') AND CONCAT(#{searchEndDate}, '239999')
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE LOGIN_ID LIKE CONCAT('%', #{query},'%') )
AND ( REPLACE(OSI.PHONE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') OR REPLACE(OSI.MOBILE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') )
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{query},'%')
AND (OI.ITEM_CODE = #{query} OR OI.ITEM_USER_CODE = #{query})
AND OSI.EMAIL LIKE CONCAT(#{query}, '%')
AND OI.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_ID IN (SELECT ITEM_ID FROM OP_ITEM WHERE ITEM_SELLER_CODE LIKE CONCAT('%', #{query},'%'))
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND (
OI.CONFIRM_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR OI.CANCEL_REQUEST_FINISH_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR OI.RETURN_REQUEST_FINISH_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR ( (OI.CONFIRM_DATE = '00000000000000' OR OI.CONFIRM_DATE IS NULL OR OI.CONFIRM_DATE = '') AND (OI.CANCEL_REQUEST_FINISH_DATE = '00000000000000' OR OI.CANCEL_REQUEST_FINISH_DATE IS NULL OR OI.CANCEL_REQUEST_FINISH_DATE = '') AND (OI.RETURN_REQUEST_FINISH_DATE = '00000000000000' OR OI.RETURN_REQUEST_FINISH_DATE IS NULL OR OI.RETURN_REQUEST_FINISH_DATE = '') ) )
ORDER BY OI.CREATED_DATE DESC, OI.ORDER_CODE DESC, OI.ORDER_SEQUENCE ASC, OI.SHIPPING_INFO_SEQUENCE ASC, OI.ITEM_SEQUENCE ASC ) T_A
AND T_A.USER_NAME_ENC = #{query}
AND T_A.CREATED_DATE <= #{createdDate}
) OI
LEFT JOIN OP_USER_DETAIL U ON OI.USER_ID = U.USER_ID
) OI

/* saleson.shop.slave.SlaveOrderMapper.getAllOrderListByParamForManager */ SELECT OI.* , IFNULL(CRYPTO_DEC('normal', USER_NAME_ENC, '', 0),'') AS USER_NAME
, IFNULL(CRYPTO_DEC('normal', MOBILE, '', 0), '') AS MOBILE_DEC , IFNULL(CRYPTO_DEC('normal', RECEIVE_ADDRESS, '', 0), '') || ' ' || IFNULL(CRYPTO_DEC('normal', RECEIVE_ADDRESS_DETAIL, '', 0), '') AS RECEIVE_ADDRESS_DEC , IFNULL(CRYPTO_DEC('normal', RECEIVE_NAME, '', 0), '') AS RECEIVE_NAME_DEC
FROM (
SELECT OI.*
, IFNULL(U.BIRTHDAY,'') AS BIRTHDAY
FROM ( SELECT * FROM ( SELECT O.LOGIN_ID , O.BUYER_NAME , OI.* , OSI.RECEIVE_NAME , (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV WHERE LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM , IFNULL(S.SELLER_NAME, '') AS SELLER_NAME , IFNULL(S.COMPANY_NAME, '') AS COMPANY_NAME , OI.USER_ID AS OI_USER_ID
, (SELECT USER_NAME FROM OP_USER WHERE USER_ID = OI.USER_ID) AS USER_NAME_ENC
, O.MOBILE , OSI.RECEIVE_MOBILE , OSI.RECEIVE_ZIPCODE , OSI.RECEIVE_NEW_ZIPCODE , OSI.RECEIVE_ADDRESS , OSI.RECEIVE_ADDRESS_DETAIL , OSI.MEMO , (SELECT OP.APPROVAL_TYPE FROM OP_ORDER_PAYMENT OP WHERE OI.ORDER_CODE = OP.ORDER_CODE AND OI.ORDER_SEQUENCE = OP.ORDER_SEQUENCE) AS APPROVAL_TYPE
, CRYPTO_DEC('normal', S.TELEPHONE_NUMBER, '', 0) AS TELEPHONE_NUMBER , CRYPTO_DEC('normal', S.PHONE_NUMBER, '', 0) AS PHONE_NUMBER , CASE WHEN OI.CAMPAIGN_CODE = 'MOBILE' THEN 'Y' ELSE 'N' END AS MOBILE_ITEM_YN , OT.ITEM_TEXT_OPTION_FLAG FROM OP_ORDER_ITEM OI
INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE INNER JOIN OP_ITEM OT ON OI.ITEM_CODE = OT.ITEM_CODE
JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND OI.SELLER_ID = #{sellerId} AND OI.DELIVERY_TYPE = '2'
AND OI.ORDER_STATUS IN
#{status}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID > #{sellerId}
AND OI.DELIVERY_TYPE = #{deliveryType}
AND OI.ORDER_STATUS IN
#{status}
AND OI.ORDER_CODE IN
#{orderCode}
AND OI.ORDER_CODE = #{orderCode}
AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.ORDER_STATUS IN
#{orderStatus}
AND OI.ORDER_STATUS = #{orderStatus}
AND OI.CANCEL_FLAG = #{cancelFlag}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y' AND O.BUYER_NAME = #{guestUserName} AND O.MOBILE = #{guestPhoneNumber}
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND OI.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime}, '9999')
AND O.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime} , '9999')
AND #{searchDateType} BETWEEN CONCAT(#{searchStartDate}, '000000') AND CONCAT(#{searchEndDate}, '239999')
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE LOGIN_ID LIKE CONCAT('%', #{query},'%') )
AND ( REPLACE(OSI.PHONE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') OR REPLACE(OSI.MOBILE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%') )
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{query},'%')
AND (OI.ITEM_CODE = #{query} OR OI.ITEM_USER_CODE = #{query})
AND OSI.EMAIL LIKE CONCAT(#{query}, '%')
AND OI.ORDER_CODE LIKE CONCAT('%', #{query} , '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query},'%')
AND OI.ITEM_ID IN (SELECT ITEM_ID FROM OP_ITEM WHERE ITEM_SELLER_CODE LIKE CONCAT('%', #{query},'%'))
AND S.LOCGOV_CODE = #{shLocgovCode}
AND S.LOCGOV_CODE IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND (
OI.CONFIRM_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR OI.CANCEL_REQUEST_FINISH_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR OI.RETURN_REQUEST_FINISH_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000') OR ( (OI.CONFIRM_DATE = '00000000000000' OR OI.CONFIRM_DATE IS NULL OR OI.CONFIRM_DATE = '') AND (OI.CANCEL_REQUEST_FINISH_DATE = '00000000000000' OR OI.CANCEL_REQUEST_FINISH_DATE IS NULL OR OI.CANCEL_REQUEST_FINISH_DATE = '') AND (OI.RETURN_REQUEST_FINISH_DATE = '00000000000000' OR OI.RETURN_REQUEST_FINISH_DATE IS NULL OR OI.RETURN_REQUEST_FINISH_DATE = '') ) )
ORDER BY OI.CREATED_DATE DESC, OI.ORDER_CODE DESC, OI.ORDER_SEQUENCE ASC, OI.SHIPPING_INFO_SEQUENCE ASC, OI.ITEM_SEQUENCE ASC ) T_A
AND T_A.USER_NAME_ENC = #{query}
AND T_A.CREATED_DATE <= #{createdDate}
) OI
LEFT JOIN OP_USER_DETAIL U ON OI.USER_ID = U.USER_ID
) OI

/* saleson.shop.slave.SlaveOrderMapper.getAllOrderCountByParamForManager */
SELECT COUNT(*)
	FROM (
		SELECT *
			FROM (
				SELECT (SELECT USER_NAME FROM OP_USER WHERE USER_ID = OI.USER_ID) AS USER_NAME


					LEFT JOIN OP_ORDER_PAYMENT OP
					ON OI.ORDER_CODE = OP.ORDER_CODE
					AND OI.ORDER_SEQUENCE = OP.ORDER_SEQUENCE



						JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID


						LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID




					AND (OI.FILLER9 IS NOT NULL OR OI.FILLER9 != '')


							AND OI.SELLER_ID = #{sellerId}
							AND OI.DELIVERY_TYPE = '2'


								AND OI.ORDER_STATUS IN

									#{status}






								AND OI.SELLER_ID = #{sellerId}




									AND OI.SELLER_ID > #{sellerId}


								AND OI.DELIVERY_TYPE = #{deliveryType}



								AND OI.ORDER_STATUS IN

									#{status}








								AND OI.ORDER_CODE IN

									#{orderCode}





								AND OI.ORDER_CODE = #{orderCode}





						AND OI.ORDER_SEQUENCE = #{orderSequence}



						AND OI.ITEM_SEQUENCE = #{itemSequence}




							AND OI.ORDER_STATUS IN

								#{orderStatus}




								AND OI.ORDER_STATUS = #{orderStatus}





						AND OI.CANCEL_FLAG = #{cancelFlag}



						AND OI.USER_ID = #{userId}
						AND OI.GUEST_FLAG = 'N'



						AND OI.GUEST_FLAG = 'Y'
						AND O.BUYER_NAME = #{guestUserName}
						AND O.MOBILE = #{guestPhoneNumber}





								AND S.LOCGOV_CODE = #{locgovCode}


								AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')





						AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')







										AND OI.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime}, '9999')


										AND O.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime}, '9999')



									AND #{searchDateType} BETWEEN CONCAT(#{searchStartDate}, '000000') AND CONCAT(#{searchEndDate}, '239999')








								AND OI.USER_ID IN (
									SELECT USER_ID FROM OP_USER
									WHERE LOGIN_ID LIKE CONCAT('%', #{query},'%')
								)


								AND (
									REPLACE(OSI.PHONE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%')
									OR REPLACE(OSI.MOBILE, '-', '') LIKE CONCAT(REPLACE(#{query}, '-', ''), '%')
								)


								AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query},'%')


								AND OI.ITEM_NAME LIKE CONCAT('%', #{query},'%')


								AND (OI.ITEM_CODE = #{query} OR OI.ITEM_USER_CODE = #{query})


								AND OSI.EMAIL LIKE CONCAT(#{query}, '%')


								AND OI.ORDER_CODE LIKE CONCAT('%', #{query} , '%')


								AND S.COMPANY_NAME LIKE CONCAT('%', #{query},'%')


								AND OI.ITEM_ID IN (SELECT ITEM_ID FROM OP_ITEM WHERE ITEM_SELLER_CODE LIKE CONCAT('%', #{query},'%'))





								AND S.LOCGOV_CODE = #{shLocgovCode}


								AND S.LOCGOV_CODE IN (
									SELECT LOCGOV.LOCGOV_CODE
										FROM G_LOCGOV LOCGOV
										WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr}
								)





								AND (
									OI.CONFIRM_DATE  >=  CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000')
									OR OI.CANCEL_REQUEST_FINISH_DATE  >=  CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000')
									OR OI.RETURN_REQUEST_FINISH_DATE  >=  CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01000000')
									OR (
										(OI.CONFIRM_DATE = '00000000000000' OR OI.CONFIRM_DATE IS NULL OR OI.CONFIRM_DATE = '')
										AND (OI.CANCEL_REQUEST_FINISH_DATE = '00000000000000' OR OI.CANCEL_REQUEST_FINISH_DATE IS NULL OR OI.CANCEL_REQUEST_FINISH_DATE = '')
										AND (OI.RETURN_REQUEST_FINISH_DATE = '00000000000000' OR OI.RETURN_REQUEST_FINISH_DATE IS NULL OR OI.RETURN_REQUEST_FINISH_DATE = '')
									)
								)



			)



						WHERE USER_NAME LIKE CONCAT('%', #{query}, '%')



		)

/* saleson.shop.slave.SlaveOrderMapper.getAllOrderListByParamForManager */ SELECT OI.* , IFNULL(CRYPTO_DEC('normal', USER_NAME_ENC, '', 0),'') AS USER_NAME
FROM (
SELECT OI.*
, IFNULL(U.BIRTHDAY, '') AS BIRTHDAY
FROM ( SELECT * FROM ( SELECT O.LOGIN_ID, O.BUYER_NAME, OI.*, OSI.RECEIVE_NAME, (SELECT UPPER_LOCGOV_NM || ' ' || LOCGOV_NM FROM G_LOCGOV WHERE LOCGOV_CODE = S.LOCGOV_CODE) AS LOCGOV_NM, IFNULL(S.SELLER_NAME, '') AS SELLER_NAME, IFNULL(S.COMPANY_NAME, '') AS COMPANY_NAME, OI.USER_ID AS OI_USER_ID, (SELECT USER_NAME FROM OP_USER WHERE USER_ID = OI.USER_ID) AS USER_NAME_ENC
, O.MOBILE , OSI.RECEIVE_MOBILE , OSI.RECEIVE_ZIPCODE , OSI.RECEIVE_NEW_ZIPCODE , OSI.RECEIVE_ADDRESS , OSI.RECEIVE_ADDRESS_DETAIL , OSI.MEMO , (SELECT OP.APPROVAL_TYPE FROM OP_ORDER_PAYMENT OP WHERE OI.ORDER_CODE = OP.ORDER_CODE AND OI.ORDER_SEQUENCE = OP.ORDER_SEQUENCE) AS APPROVAL_TYPE
, CASE WHEN OI.CAMPAIGN_CODE = 'MOBILE' THEN 'Y' ELSE 'N' END AS MOBILE_ITEM_YN FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1'
INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE
JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND (OI.FILLER9 IS NOT NULL OR OI.FILLER9 != '')
AND OI.SELLER_ID = #{sellerId} AND OI.DELIVERY_TYPE = '2'
AND OI.ORDER_STATUS IN
#{status}
AND OI.SELLER_ID = #{sellerId}
AND OI.SELLER_ID > #{sellerId}
AND OI.DELIVERY_TYPE = #{deliveryType}
AND OI.ORDER_STATUS IN
#{status}
AND OI.ORDER_CODE IN
#{orderCode}
AND OI.ORDER_CODE = #{orderCode}
AND OI.ORDER_SEQUENCE = #{orderSequence}
AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.ORDER_STATUS IN
#{orderStatus}
AND OI.ORDER_STATUS = #{orderStatus}
AND OI.CANCEL_FLAG = #{cancelFlag}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y' AND O.BUYER_NAME = #{guestUserName} AND O.MOBILE = #{guestPhoneNumber}
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE LIKE CONCAT(SUBSTR(#{upperLocgovCode}, 0, 2), '%')
AND OI.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND OI.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime}, '9999')
AND O.CREATED_DATE BETWEEN CONCAT(#{searchStartDate},#{searchStartDateTime}, '0000') AND CONCAT(#{searchEndDate},#{searchEndDateTime} , '9999')
AND #{searchDateType} BETWEEN CONCAT(#{searchStartDate}, '000000') AND CONCAT(#{searchEndDate}, '239999')
